import { createElement } from "./sidebar";
import { format } from "date-fns";

export class createModal {
  constructor() {}
  renderModal(data) {
    const options = new createElement({
      element: "select",
      name: "todoPrio",
    }).generateElement();
    const additionalOptions = new createElement({
      element: "div",
      className: "additional-input",
    }).generateElement();
    const header = new createElement({
      element: "div",
      className: "modal-header",
    }).generateElement();
    const body = new createElement({
      element: "div",
      className: "modal-body",
    }).generateElement();
    const form = new createElement({
      element: "form",
    }).generateElement();
    const submitButton = new createElement({
      element: "button",
      content: data.buttonText,
      className: "button-submit",
    }).generateElement();

    const title = new createElement({
      element: "h3",
      content: data.modalData.content,
    }).generateElement();
    const close = new createElement({
      element: "span",
      className: "mdi mdi-close",
      id: "close-modal",
    }).generateElement();
    data.modalData.inputEle.forEach((ev) => {
      if (ev.additionalInput) {
        ev.additionalInput.forEach((event) => {
          if (event.select) {
            event.select.forEach((priorityList) => {
              options.append(priorityList.createEle);
            });
          }
          additionalOptions.append(
            event.createEle !== undefined ? event.createEle : "",
            options
          );
        });
      }
      form.append(ev.createEle ? ev.createEle : "", additionalOptions);
    });
    form.addEventListener("submit", (ev) => {
      ev.preventDefault();
      data.formToInsert({
        formData: ev.target,
        data,
      });
      ev.target.reset();
    });
    close.addEventListener("click", (ev) => {
      document.getElementById("modal").style.visibility = "hidden";
    });
    form.append(submitButton);
    body.appendChild(form);
    header.append(title, close);
    return [header, body];
  }
}

export class formHandler {
  constructor() {}
  formInsertProject(data) {
    if (data.formData.name.value === "") return;
    if (localStorage.getItem("projects")) {
      const currentValue = JSON.parse(localStorage.getItem("projects")) || [];
      currentValue.push({
        projectName: data.formData.name.value,
        section: [],
      });
      localStorage.setItem("projects", JSON.stringify(currentValue));
    } else {
      localStorage.setItem(
        "projects",
        JSON.stringify([
          {
            projectName: data.formData.name.value,
            section: [],
          },
        ])
      );
    }
    data.data.eleToRender();
  }

  formInsertSection(data) {
    const sectionName = data.formData.name.value;
    if (sectionName === "") return;
    const currentValue = JSON.parse(localStorage.getItem("projects")) || [];
    currentValue[data.index].section.push({
      sectionName: sectionName === "" ? "No Section" : sectionName,
      todoList: [],
    });
    localStorage.setItem("projects", JSON.stringify(currentValue));
  }
  formInsertTodo(data) {
    if (data.formData.todoTitle.value === "") return;
    const section = JSON.parse(localStorage.getItem("projects"));
    section[data.data.projectId].section[data.data.sectionId].todoList.push({
      todoTitle: data.formData.todoTitle.value,
      todoDesc: data.formData.todoDesc.value,
      todoDate: data.formData.todoDate.value,
      todoTime: data.formData.todoTime.value,
      todoPrio: data.formData.todoPrio.value,
    });
    localStorage.setItem("projects", JSON.stringify(section));
    data.data.eleToRender();
  }
  formUpdateSection(data) {
    if (data.formData.sectionTitle.value === "") return;
    const section = JSON.parse(localStorage.getItem("projects")) || [];
    section[data.data.projectId].section[data.data.sectionId].sectionName =
      data.formData.sectionTitle.value;
    localStorage.setItem("projects", JSON.stringify(section));
    data.data.eleToRender();
  }
  formUpdateTodo(data) {
    if (data.formData.todoTitle.value === "") return;
    const projects = JSON.parse(localStorage.getItem("projects")) || [];
    projects[data.data.projectId].section[data.data.sectionId].todoList[
      data.data.todoId
    ].todoTitle = data.formData.todoTitle.value;
    projects[data.data.projectId].section[data.data.sectionId].todoList[
      data.data.todoId
    ].todoDesc = data.formData.todoDesc.value;
    projects[data.data.projectId].section[data.data.sectionId].todoList[
      data.data.todoId
    ].todoDate = data.formData.todoDate.value;
    projects[data.data.projectId].section[data.data.sectionId].todoList[
      data.data.todoId
    ].todoTime = data.formData.todoTime.value;
    projects[data.data.projectId].section[data.data.sectionId].todoList[
      data.data.todoId
    ].todoPrio = data.formData.todoPrio.value;

    localStorage.setItem("projects", JSON.stringify(projects));
    data.data.eleToRender();
  }
  formUpdateGroup(data) {
    if (data.formData.projectName.value === "") return;
    const projects = JSON.parse(localStorage.getItem("projects")) || [];
    projects[data.data.projectId].projectName = data.formData.projectName.value;
    localStorage.setItem("projects", JSON.stringify(projects));
    data.data.eleToRender();
  }
  insertTodoDep(data) {
    if (data.formData.todoTitle.value === "") return;
    const dataToInsert = {
      projectName: "",
      section: [
        {
          sectionName: "",
          todoList: [
            {
              todoTitle: data.formData.todoTitle.value,
              todoDesc: data.formData.todoDesc.value,
              todoDate: data.formData.todoDate.value,
              todoTime: data.formData.todoTime.value,
              todoPrio: data.formData.todoPrio.value,
            },
          ],
        },
      ],
    };

    if (localStorage.getItem("projects")) {
      const currentValue = JSON.parse(localStorage.getItem("projects")) || [];
      currentValue.push(dataToInsert);
      localStorage.setItem("projects", JSON.stringify(currentValue));
    } else {
      localStorage.setItem("projects", JSON.stringify([dataToInsert]));
    }
    data.data.eleToRender();
  }
}
