export class createElement {
  constructor(data) {
    this.data = data;
  }
  generateElement() {
    const ele = document.createElement(this.data.element);

    if (this.data.className) ele.classList = this.data.className;
    if (this.data.content) ele.innerHTML = this.data.content;
    if (this.data.id) ele.id = this.data.id;
    if (this.data.name) ele.name = this.data.name;
    if (this.data.type) ele.type = this.data.type;
    if (this.data.value) ele.value = this.data.value;
    if (this.data.style) ele.style = this.data.style;
    if (this.data.listener)
      ele.addEventListener(this.data.listener.type, (event) => {
        event.stopPropagation();
        this.data.listener.content();
      });

    return ele;
  }
}
