import { createElement } from "./sidebar";
import { formHandler } from "./modal-handler";
import {
  format,
  isBefore,
  isToday,
  isTomorrow,
  differenceInCalendarDays,
  formatDate,
} from "date-fns";

export class taskList {
  constructor(data) {
    this.data = data;
  }
  renderTaskToday() {
    const data = this.data;
    const navbar = new createElement({ element: "nav" }).generateElement();
    const taskContainer = new createElement({
      element: "div",
      className: "groups-content",
    }).generateElement();
    const title = new createElement({
      element: "h2",
      content: this.data.title,
    }).generateElement();
    const sectionContainer = new createElement({
      element: "div",
      className: "section-container",
    }).generateElement();
    const todoState = ["Overdue", "Today", "Upcoming"];

    function getSec() {
      const projects = JSON.parse(localStorage.getItem("projects"));
      sectionContainer.textContent = "";
      todoState.forEach((state) => {
        const addButton = new createElement({
          element: "span",
          className: "mdi mdi-plus-circle-outline",
          content: " Add Todo",
          listener: {
            type: "click",
            content: () => {
              data.func({
                modalData: modalDataTodo({
                  todoTitle: "",
                  todoDesc: "",
                  todoDate: format(new Date(), "yyyy-MM-dd"),
                  todoTime: "",
                  formTitle: "Add Todo",
                }),
                formToInsert: new formHandler().insertTodoDep,
                eleToRender: getSec,
                buttonText: "Add",
              });
            },
          },
        }).generateElement();
        const todoBody = new createElement({
          element: "div",
        }).generateElement();
        const todoContainer = new createElement({
          element: "div",
          className: "todo-content",
        }).generateElement();
        const stateTitle = new createElement({
          element: "h4",
          content:
            state === "Today"
              ? `${state} • ${format(new Date(), "MMM dd")}`
              : state,
        }).generateElement();

        if (projects)
          projects.forEach((projectData, projectIndex) => {
            projectData.section.forEach((sectionData, sectionIndex) => {
              sectionData.todoList.map((todoData, todoIndex) => {
                const todoList = new todoListHandler(
                  todoData,
                  todoIndex,
                  sectionIndex,
                  projectIndex,
                  data.func,
                  getSec,
                  sectionData.sectionName,
                  projectData.projectName
                ).renderTodo();

                if (state === "Overdue") {
                  if (
                    differenceInCalendarDays(new Date(), todoData.todoDate) > 0
                  )
                    todoBody.append(todoList);
                }
                if (state === "Today") {
                  if (isToday(todoData.todoDate)) todoBody.append(todoList);
                }
                if (state === "Upcoming") {
                  if (
                    differenceInCalendarDays(todoData.todoDate, new Date()) > 0
                  )
                    todoBody.append(todoList);
                }
              });
            });
          });

        todoContainer.append(
          stateTitle,
          todoBody,
          state === "Today" ? addButton : " "
        );
        sectionContainer.append(todoContainer);
      });
    }
    getSec();
    taskContainer.append(title, sectionContainer);
    navbar.append("ToDo");
    return [navbar, taskContainer];
  }
  renderTaskCompleted() {
    const navbar = new createElement({ element: "nav" }).generateElement();
    navbar.append("ToDo");
    const completedContainer = new createElement({
      element: "div",
      className: "completed-container",
    }).generateElement();
    const dateIndicator = new createElement({
      element: "h4",
      content: "No completed task currently",
      style: "color:gray",
    }).generateElement();
    const title = new createElement({
      element: "h2",
      content: "Completed Task",
    }).generateElement();

    const todoCompleted = JSON.parse(localStorage.getItem("completedTodo"));

    const getTodos = () => {
      const contentContainer = new createElement({
        element: "div",
      }).generateElement();

      const dateGroup = Object.groupBy(todoCompleted, (todo) =>
        format(todo.completedDate, "MMM dd yyyy")
      );

      for (const compDate in dateGroup) {
        const todoCompletedDate = new createElement({
          element: "h4",
          content: `${compDate} • ${format(compDate, "eeee")}`,
        }).generateElement();
        const todoBodyContainer = new createElement({
          element: "div",
        }).generateElement();

        dateGroup[compDate].forEach((todo) => {
          const todoBodyContent = new createElement({
            element: "div",
          }).generateElement();
          const todoTitle = new createElement({
            element: "span",
            content: `The task <em>${todo.todo.todoTitle}</em> has been completed.`,
          }).generateElement();
          const todoTimeCompleted = new createElement({
            element: "span",
            content: format(todo.completedDate, "hh:mm"),
            style: "color:gray",
          }).generateElement();
          const todoDesc = new createElement({
            element: "span",
            content: todo.todo.todoDesc,
            style: "color:rgb(230, 230, 230)",
          }).generateElement();
          todoBodyContent.append(todoTitle, todoDesc, todoTimeCompleted);
          todoBodyContainer.append(todoBodyContent);
        });
        contentContainer.append(todoCompletedDate, todoBodyContainer);
      }
      return contentContainer;
    };

    completedContainer.append(
      title,
      todoCompleted ? getTodos() : dateIndicator
    );

    return [navbar, completedContainer];
  }
}

export class sectionList {
  constructor(data) {
    this.data = data;
  }
  renderContent() {
    const data = this.data;
    const navbar = new createElement({ element: "nav" }).generateElement();
    const groupTitle = new createElement({
      element: "span",
      content: this.data.headerTitle,
    }).generateElement();
    navbar.append(groupTitle);
    const groupContent = new createElement({
      element: "div",
      className: "groups-content",
    }).generateElement();
    const groupName = new createElement({
      element: "h2",
      content: this.data.groupName,
    }).generateElement();

    const sectionContainer = new createElement({
      element: "div",
      className: "section-container",
    }).generateElement();
    const sectionForm = new createElement({
      element: "form",
    }).generateElement();

    function getSec() {
      sectionContainer.textContent = "";
      const sections = JSON.parse(localStorage.getItem("projects"))[data.index]
        .section;

      if (sections.length > 0) {
        sections.forEach((val, index) => {
          sectionContainer.append(
            new getSection(
              val,
              data.func,
              index,
              data.index,
              getSec
            ).getSection()
          );
        });
      }
      sectionContainer.append(sectionForm);
    }
    getSec();

    const sectionSubmitContainer = new createElement({
      element: "div",
    }).generateElement();
    const sectionLabel = new createElement({
      element: "span",
      content: "Section Name",
    }).generateElement();
    const inputSection = new createElement({
      element: "input",
      type: "text",
      name: "name",
    }).generateElement();
    const showSectionOptions = new createElement({
      element: "span",
      content: " Add Section",
      className: "mdi mdi-plus-circle-outline",
    }).generateElement();
    showSectionOptions.addEventListener("click", (event) => {
      showSectionOptions.style = "display:none";
      sectionSubmitContainer.style = "visibility:visible";
    });
    const sectionSubmit = new createElement({
      element: "button",
      type: "submit",
      content: "Add",
      className: "button-submit",
    }).generateElement();
    const cancelSection = new createElement({
      element: "span",
      content: "Cancel",
      className: "button-cancel",
    }).generateElement();
    cancelSection.addEventListener("click", (event) => {
      showSectionOptions.style = "display:block";
      sectionSubmitContainer.style = "visibility:hidden";
    });

    sectionForm.addEventListener("submit", (ev) => {
      ev.preventDefault();
      new formHandler().formInsertSection({
        index: this.data.index,
        formData: ev.target,
      });
      ev.target.reset();
      getSec();
    });
    sectionSubmitContainer.append(
      sectionLabel,
      inputSection,
      sectionSubmit,
      cancelSection
    );
    sectionForm.append(showSectionOptions, sectionSubmitContainer);
    groupContent.append(groupName, sectionContainer);

    return [navbar, groupContent];
  }
}

class getSection {
  constructor(sections, func, sectionId, projectId, eleToRender) {
    this.sections = sections;
    this.func = func;
    this.sectionIndex = sectionId;
    this.projectIndex = projectId;
    this.eleToRender = eleToRender;
  }
  getSection() {
    const todoBody = new createElement({
      element: "div",
    }).generateElement();
    const todoContent = new createElement({
      element: "div",
      className: "todo-content",
    }).generateElement();
    const sectionTitle = new createElement({
      element: "h3",
      content: this.sections.sectionName,
    }).generateElement();
    const sectionTitleContainer = new createElement({
      element: "div",
    }).generateElement();
    const sectionEdit = new createElement({
      element: "span",
      className: "mdi mdi-pencil-box-multiple-outline",
      style: "color:rgb(52, 134, 185);cursor:pointer;font-size:16px",
    }).generateElement();
    const sectionDelete = new createElement({
      element: "span",
      className: "mdi mdi-trash-can-outline",
      style: "color:red;cursor:pointer;font-size:16px",
    }).generateElement();
    sectionDelete.addEventListener("click", (event) => {
      if (confirm("Are you sure?")) {
        const sectionData = JSON.parse(localStorage.getItem("projects"));
        sectionData[this.projectIndex].section.splice(this.sectionIndex, 1);
        localStorage.setItem("projects", JSON.stringify(sectionData));
        this.eleToRender();
      }
    });
    sectionEdit.addEventListener("click", (event) => {
      this.func({
        modalData: {
          content: "Update Section",
          inputEle: [
            {
              createEle: new createElement({
                element: "input",
                type: "text",
                value: this.sections.sectionName,
                name: "sectionTitle",
              }).generateElement(),
            },
          ],
        },
        formToInsert: new formHandler().formUpdateSection,
        eleToRender: this.eleToRender,
        sectionId: this.sectionIndex,
        projectId: this.projectIndex,
        buttonText: "Update",
      });
    });
    sectionTitleContainer.append(sectionTitle, sectionEdit, sectionDelete);
    if (this.sections.todoList.length > 0) {
      this.sections.todoList.forEach((todoData, todoIndex) => {
        todoBody.append(
          new todoListHandler(
            todoData,
            todoIndex,
            this.sectionIndex,
            this.projectIndex,
            this.func,
            this.eleToRender
          ).renderTodo()
        );
      });
    }
    const addButton = new createElement({
      element: "span",
      className: "mdi mdi-plus-circle-outline",
      content: " Add Todo",
    }).generateElement();
    addButton.addEventListener("click", (event) => {
      this.func({
        modalData: modalDataTodo({
          todoTitle: "",
          todoDesc: "",
          todoDate: "",
          todoTime: "",
          formTitle: "Add Todo",
        }),
        formToInsert: new formHandler().formInsertTodo,
        sectionId: this.sectionIndex,
        projectId: this.projectIndex,
        eleToRender: this.eleToRender,
        buttonText: "Add",
      });
    });
    todoContent.append(sectionTitleContainer, todoBody, addButton);
    return todoContent;
  }
}
function modalDataTodo(data) {
  return {
    content: data.formTitle,
    inputEle: [
      {
        createEle: new createElement({
          element: "span",
          content: "Todo Title",
        }).generateElement(),
      },
      {
        createEle: new createElement({
          element: "input",
          type: "text",
          name: "todoTitle",
          value: data.todoTitle,
        }).generateElement(),
      },
      {
        createEle: new createElement({
          element: "span",
          content: "Description",
        }).generateElement(),
      },
      {
        createEle: new createElement({
          element: "input",
          type: "text",
          name: "todoDesc",
          value: data.todoDesc,
        }).generateElement(),
      },
      {
        additionalInput: [
          {
            createEle: new createElement({
              element: "input",
              type: "date",
              name: "todoDate",
              value: data.todoDate,
            }).generateElement(),
          },

          {
            createEle: new createElement({
              element: "input",
              type: "time",
              name: "todoTime",
              value: data.todoTime,
            }).generateElement(),
          },
          {
            select: [
              {
                createEle: new createElement({
                  element: "option",
                  value: "1",
                  content: "Priority 1",
                }).generateElement(),
              },
              {
                createEle: new createElement({
                  element: "option",
                  value: "2",
                  content: "Priority 2",
                }).generateElement(),
              },
              {
                createEle: new createElement({
                  element: "option",
                  value: "3",
                  content: "Priority 3",
                }).generateElement(),
              },
              {
                createEle: new createElement({
                  element: "option",
                  value: "4",
                  content: "Priority 4",
                }).generateElement(),
              },
            ],
          },
        ],
      },
    ],
  };
}

class todoListHandler {
  constructor(
    todoData,
    todoIndex,
    sectionIndex,
    projectIndex,
    modalFunc,
    renderHandler,
    todoSection = "",
    todoProject = ""
  ) {
    this.todoData = todoData;
    this.todoIndex = todoIndex;
    this.sectionIndex = sectionIndex;
    this.projectIndex = projectIndex;
    this.renderHandler = renderHandler;
    this.modalFunc = modalFunc;
    this.todoSection = todoSection;
    this.todoProject = todoProject;
  }
  renderTodo() {
    const isCompelete = new createElement({
      element: "input",
      type: "checkbox",
      style: this.priority(this.todoData.todoPrio),
    }).generateElement();

    isCompelete.addEventListener("click", () => {
      this.markAsComplete({
        todoIndex: this.todoIndex,
        sectionIndex: this.sectionIndex,
        projectIndex: this.projectIndex,
        renderHandler: this.renderHandler,
      });
    });
    const todoBody = new createElement({
      element: "div",
      className: "todo-body",
    }).generateElement();
    const optionContainer = new createElement({
      element: "div",
    }).generateElement();
    const deleteTodo = new createElement({
      element: "span",
      className: "mdi mdi-trash-can-outline",
      style: "color:red;cursor:pointer;font-size:16px",
    }).generateElement();
    deleteTodo.addEventListener("click", (event) => {
      this.deleteTodoHandler({
        todoIndex: this.todoIndex,
        sectionIndex: this.sectionIndex,
        projectIndex: this.projectIndex,
        renderHandler: this.renderHandler,
      });
    });

    const editTodo = new createElement({
      element: "span",
      className: "mdi mdi-pencil-box-multiple-outline",
      style: "color:rgb(52, 134, 185);cursor:pointer;font-size:16px",
    }).generateElement();
    editTodo.addEventListener("click", () => {
      this.modalFunc({
        modalData: modalDataTodo({
          todoTitle: this.todoData.todoTitle,
          todoDesc: this.todoData.todoDesc,
          todoDate: this.todoData.todoDate,
          todoTime: this.todoData.todoTime,
          formTitle: "Update Todo",
        }),
        formToInsert: new formHandler().formUpdateTodo,
        todoId: this.todoIndex,
        sectionId: this.sectionIndex,
        projectId: this.projectIndex,
        eleToRender: this.renderHandler,
        buttonText: "Update",
      });
    });
    optionContainer.append(editTodo, isCompelete, deleteTodo);
    const todoDesc = new createElement({
      element: "div",
    }).generateElement();
    const todoTitle = new createElement({
      element: "h5",
      content: this.todoData.todoTitle,
    }).generateElement();
    const todoDescription = new createElement({
      element: "p",
      content:
        this.todoData.todoDesc !== ""
          ? this.todoData.todoDesc
          : "No Description",
    }).generateElement();
    const timeContainer = new createElement({
      element: "div",
      className: "time-container",
    }).generateElement();
    const todoDate = this.todoData.todoDate
      ? new createElement({
          element: "span",
          content: " " + this.dateSetup(this.todoData.todoDate)[0],
          className: "mdi mdi-calendar-range",
          style: this.dateSetup(this.todoData.todoDate)[1],
        }).generateElement()
      : "";
    const todoTime = this.todoData.todoTime
      ? new createElement({
          element: "span",
          content: " " + this.todoData.todoTime,
          className: "mdi mdi-clock-outline",
        }).generateElement()
      : "";
    const todoSection = new createElement({
      element: "span",
      content: this.todoSection,
    }).generateElement();
    const todoProject = new createElement({
      element: "span",
      content: this.todoProject,
    }).generateElement();
    timeContainer.append(todoDate, todoTime, todoSection, todoProject);
    todoDesc.append(todoTitle, todoDescription, timeContainer);
    todoBody.append(optionContainer, todoDesc);
    return todoBody;
  }
  dateSetup(date) {
    if (isToday(date)) {
      return ["Today", "color:#FFA500"];
    }
    if (isTomorrow(date)) {
      return ["Tomorrow", "color:#FFD700"];
    }
    if (isBefore(date, new Date())) {
      return [format(date, "dd/MM"), "color:rgb(238, 92, 92)"];
    } else {
      if (differenceInCalendarDays(date, new Date()) > 5)
        return [format(date, "MM/dd"), "color:#32CD32"];
      else return [format(date, "EEEE"), "color:#32CD32"];
    }
  }
  priority(prio) {
    prio = parseInt(prio);
    if (prio === 1) return "border:1px solid red";
    if (prio === 2) return "border:1px solid orange";
    if (prio === 3) return "border:1px solid yellow";
    if (prio === 4) return "border:1px solid gray";
  }
  deleteTodoHandler(data) {
    if (confirm("Are u sure?")) {
      const projects = JSON.parse(localStorage.getItem("projects"));
      if (projects[data.projectIndex].projectName === "")
        projects.splice(data.projectIndex, 1);
      else {
        projects[data.projectIndex].section[data.sectionIndex].todoList.splice(
          data.todoIndex,
          1
        );
      }
      localStorage.setItem("projects", JSON.stringify(projects));
      data.renderHandler();
    } else return;
  }
  markAsComplete(data) {
    const todo = JSON.parse(localStorage.getItem("projects"));
    if (JSON.parse(localStorage.getItem("completedTodo"))) {
      const completedTodo =
        JSON.parse(localStorage.getItem("completedTodo")) || [];

      completedTodo.push({
        completedDate: new Date(),
        todo: todo[data.projectIndex].section[data.sectionIndex].todoList[
          data.todoIndex
        ],
      });
      localStorage.setItem("completedTodo", JSON.stringify(completedTodo));
    } else {
      todo[data.projectIndex].section[data.sectionIndex].todoList[
        data.todoIndex
      ];
      localStorage.setItem(
        "completedTodo",
        JSON.stringify([
          {
            completedDate: new Date(),
            todo: todo[data.projectIndex].section[data.sectionIndex].todoList[
              data.todoIndex
            ],
          },
        ])
      );
    }
    todo[data.projectIndex].section[data.sectionIndex].todoList.splice(
      data.todoIndex,
      1
    );
    localStorage.setItem("projects", JSON.stringify(todo));
    data.renderHandler();
  }
}
