import "./style.css";
import { createElement } from "./components/sidebar";
import { createModal, formHandler } from "./components/modal-handler";
import { sectionList, taskList } from "./components/task";

function hideHandler(clickId, container, className) {
  document.querySelectorAll(clickId).forEach((val) => {
    const groupsContainer = document.getElementById(container);
    val.addEventListener("click", (ev) => {
      if (groupsContainer.classList.contains(className)) {
        groupsContainer.classList.remove(className);
      } else {
        groupsContainer.classList.add(className);
      }
    });
  });
}

function sidebarHandler() {
  document.getElementById("create-group").addEventListener("click", () => {
    modalHandler({
      modalData: {
        content: "Project",
        inputEle: [
          {
            createEle: new createElement({
              element: "span",
              content: "Name",
            }).generateElement(),
          },
          {
            createEle: new createElement({
              element: "input",
              name: "name",
              type: "text",
            }).generateElement(),
          },
        ],
      },
      formToInsert: new formHandler().formInsertProject,
      eleToRender: renderGroupHandler,
      buttonText: "Add",
    });
  });
}

function renderGroupHandler() {
  const groupsContainer = document.getElementById("groups");
  const groupContent = document.getElementById("content");

  document
    .getElementById("todo-container")
    .querySelectorAll("span")
    .forEach((ele, index) => {
      let projectIndex = 0;
      const project = JSON.parse(localStorage.getItem("projects"));
      if (project) {
        project.forEach((data, id) => {
          if (data.projectName === "") projectIndex = id;
        });
      }

      function getTodoToday(ele) {
        document
          .getElementById("side-bar")
          .querySelectorAll("span,div")
          .forEach((val) => {
            val.classList.remove("active");
          });

        getTodo({
          contentContainer: groupContent,
          title: ele.dataset.tab,
          func: modalHandler,
          index: projectIndex,
        });
        ele.classList = "active";
      }

      ele.addEventListener("click", () => {
        groupContent.textContent = "";
        getTodoToday(ele);
      });
      if (index === 0) {
        getTodoToday(ele);
      }
    });

  function groupsRenderHandler() {
    groupsContainer.textContent = "";
    const projects = JSON.parse(localStorage.getItem("projects"));
    if (!projects || projects.length <= 0) return;
    projects.forEach((ev, index) => {
      if (ev.projectName === "") return;
      const groupName = new createElement({
        element: "span",
        content: ev.projectName,
      }).generateElement();
      const container = new createElement({
        element: "div",
        listener: {
          type: "click",
          content: () => {
            document
              .getElementById("side-bar")
              .querySelectorAll("div,span")
              .forEach((val) => {
                val.classList.remove("active");
              });

            container.classList = "active";
            groupContent.textContent = "";
            const contentContainer = new sectionList({
              headerTitle: "Project",
              groupName: ev.projectName,
              index: index,
              func: modalHandler,
            }).renderContent();
            groupContent.append(contentContainer[0], contentContainer[1]);
          },
        },
      }).generateElement();

      const editGroup = new createElement({
        element: "span",
        className: "mdi mdi-pencil-box-multiple-outline",
        style: "color:rgb(52, 134, 185);cursor:pointer;font-size:16px",
        listener: {
          type: "click",
          content: () => {
            modalHandler({
              modalData: {
                content: "Update Project",
                inputEle: [
                  {
                    createEle: new createElement({
                      element: "input",
                      type: "text",
                      value: ev.projectName,
                      name: "projectName",
                    }).generateElement(),
                  },
                ],
              },
              formToInsert: new formHandler().formUpdateGroup,
              eleToRender: groupsRenderHandler,
              projectId: index,
              buttonText: "Update",
            });
          },
        },
      }).generateElement();

      const deleteGroup = new createElement({
        element: "span",
        className: "mdi mdi-trash-can-outline",
        style: "color:red;cursor:pointer;font-size:16px",
        listener: {
          type: "click",
          content: () => {
            if (confirm("Are you sure?")) {
              projects.splice(index, 1);
              localStorage.setItem("projects", JSON.stringify(projects));
              groupsRenderHandler();
            }
          },
        },
      }).generateElement();

      const optionContainer = new createElement({
        element: "div",
        className: "options-container",
      }).generateElement();

      optionContainer.append(editGroup, deleteGroup);
      container.append(groupName, optionContainer);
      groupsContainer.append(container);
    });
  }
  groupsRenderHandler();
}

function getTodo(data) {
  let contentContainer = "";
  if (data.title === "Completed") {
    contentContainer = new taskList({
      title: data.title,
      projectIndex: data.index,
    }).renderTaskCompleted();
  }

  if (data.title === "Today") {
    contentContainer = new taskList({
      title: data.title,
      func: modalHandler,
      projectIndex: data.index,
    }).renderTaskToday();
  }

  data.contentContainer.append(contentContainer[0], contentContainer[1]);
}

function modalHandler(data) {
  const modalContent = document.getElementById("modal-content");
  const mainModal = document.getElementById("modal");
  modalContent.textContent = "";
  const modalCreation = new createModal().renderModal(data);
  modalContent.append(modalCreation[0], modalCreation[1]);
  mainModal.style.visibility = "visible";
}

renderGroupHandler();
sidebarHandler();
hideHandler(".hide-group", "groups", "hidden");
hideHandler(".menu-hide", "side-bar", "show");
hideHandler(".menu-hide", "side-bar-container", "show");

document.getElementById("side-bar").addEventListener("click", (event) => {
  if (event.target.id === "side-bar") {
    document.getElementById("side-bar-container").classList.remove("show");
    document.getElementById("side-bar").classList.remove("show");
  }
});
